/*

Write a single UPDATE statement that sets the `adherence_tier` column as follows: 

if `refill_percentage_90d >= 80.0`, set `adherence_tier` to 'gold'; 
if `refill_percentage_90d >= 60.0` (but less than 80), set `adherence_tier` to 'silver'; otherwise set `adherence_tier` to 'bronze'.


After the UPDATE, return all rows from `patient_adherence` ordered by `patient_id` ascending.
 */

UPDATE patient_adherence
SET adherence_tier = CASE WHEN refill_percentage_90d >= 80.0 THEN 'gold'
                          WHEN refill_percentage_90d >= 60.0 and refill_percentage_90d < 80.0 THEN 'silver'
                          ELSE 'bronze' END;



SELECT * FROM patient_adherence ORDER BY patient_id;
